ClearAll[m,p,h,l,eta,zeta,fc,fd,mu,mut,v,g0,g1,g2,al,be,th,ion,k1,k2];
h=p+m;l=p+2m;eta=m/l;zeta=h/l;fc=p/h;fd=m/h;mu=m*h/l;mut=m*p/h;
v0e=v+zeta*g0;v0h=v-eta*g0;v1=v+zeta*g1;v2=v-eta*g1+fc*g2;vp=v-eta*g1-fd*g2;
eventMomentum=Together[m*v1+m*v2+p*vp-m*v0e-h*v0h];
incomingEnergy=Together[(m*v0e^2+h*v0h^2-l*v^2-mu*g0^2)/2];
outgoingEnergy=Together[(m*v1^2+m*v2^2+p*vp^2-l*v^2-mu*g1^2-mut*g2^2)/2];
qe=(3 eta/2+2 eta fd) th al-eta fd be-fc ion al;
qh=-3 zeta th al/2-eta be;
qp=(3(zeta-eta)/2-2eta fd) th al+fd be-fd ion al;
a=eta^2 al+2eta zeta k1+zeta^2 k2;b=zeta^2 al+2eta zeta k1+eta^2 k2;c0=eta zeta(al-2k1+k2);
colE=Together[2eta^2 al-a-c0+eta(zeta-eta)al+zeta k2];
colH=Together[2eta zeta al-c0-b+zeta(zeta-eta)al+eta k2];
heavyDirect=Together[qh+qp-(-(3 eta/2+2eta fd)th al+eta fd be-fd ion al)];
